import marshal, os, glob, re
for p in sorted(glob.glob('tests/__pycache__/*.pyc')):
    src = p.split('/')[-1].split('.')[0] + '.py'
    data=open(p,'rb').read()
    try:
        code=marshal.loads(data[16:])
    except Exception as e:
        print(p, 'ERR', e); continue
    names=[]
    def walk(c):
        for const in c.co_consts:
            if hasattr(const,'co_name'):
                if const.co_name.startswith('test'):
                    names.append(const.co_name)
                walk(const)
    walk(code)
    cur=set()
    if os.path.exists('tests/'+src):
        txt=open('tests/'+src).read()
        cur=set(re.findall(r'^def (test\w+)', txt, re.M))
    missing=[n for n in names if n not in cur]
    print(src, 'pyc tests:', len(names), 'missing in source:', missing)
EOF

